// Verifies the OS signature: HMAC-SHA256(secret, `${timestamp}.${nonce}.${body}`), max 5 minutes old.
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto and DP_SIGNING_SECRET (same value as N8N_SIGNING_SECRET in the OS).
const crypto = require('crypto');
const item = $input.first();
const h = item.json.headers || {};
const secret = $env.DP_SIGNING_SECRET || '';
const raw = item.binary && item.binary.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : JSON.stringify(item.json.body);
const ts = String(h['x-dp-timestamp'] || ''), nonce = String(h['x-dp-nonce'] || ''), sig = String(h['x-dp-signature'] || '');
let ok = Boolean(secret) && /^\d{9,11}$/.test(ts) && nonce.length >= 16 && nonce.length <= 128 && /^[0-9a-f]{64}$/.test(sig)
  && Math.abs(Math.floor(Date.now() / 1000) - Number(ts)) <= 300;
if (ok) {
  const expected = crypto.createHmac('sha256', secret).update(`${ts}.${nonce}.${raw}`).digest();
  const given = Buffer.from(sig, 'hex');
  ok = given.length === expected.length && crypto.timingSafeEqual(given, expected);
}
let payload = {};
try { payload = JSON.parse(raw); } catch (e) { ok = false; }
const runOk = ok && /^[0-9a-f-]{36}$/.test(String(payload.run_id || '')) && /^[0-9a-f-]{36}$/.test(String(payload.organization_id || ''));
return [{ json: { ok: runOk, run_id: payload.run_id, organization_id: payload.organization_id, input: payload.input || {} } }];

const s = $('Verify signature').first().json.input; const org = $('Verify signature').first().json.organization_id;
const headers = { 'x-api-key': $env.DP_APOLLO_API_KEY, 'Content-Type': 'application/json', 'Cache-Control': 'no-cache' };
const page = (Math.floor(Date.now() / 86400000) % 20) + 1; // a different page each day; duplicates are skipped by the OS anyway
const out = [];
for (const q of s.searches || []) {
  const body = { per_page: Math.min(q.per_run || 25, 100), page, person_titles: q.titles || [], person_locations: q.locations || [],
    organization_num_employees_ranges: q.employee_ranges || [], ...(q.keywords ? { q_keywords: q.keywords } : {}) };
  let found = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.apollo.io/api/v1/mixed_people/api_search', headers, body, json: true });
  if (!(found.people || []).length && page > 1) found = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.apollo.io/api/v1/mixed_people/api_search', headers, body: { ...body, page: 1 }, json: true });
  const ids = (found.people || []).map((p) => p.id).filter(Boolean);
  for (let i = 0; i < ids.length; i += 10) {
    const m = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.apollo.io/api/v1/people/bulk_match', headers, json: true,
      body: { details: ids.slice(i, i + 10).map((id) => ({ id })), reveal_personal_emails: false, reveal_phone_number: false } });
    for (const p of m.matches || []) {
      if (!p || !p.email || p.email_status !== 'verified') continue; // never send to guessed or unverified addresses
      const name = p.name || [p.first_name, p.last_name].filter(Boolean).join(' ');
      if (!name) continue;
      out.push({ json: { payload: { type: 'lead', organization_id: org, full_name: name.slice(0, 200), email: p.email,
        ...(p.organization && p.organization.name ? { company_name: String(p.organization.name).slice(0, 200) } : {}),
        ...(p.linkedin_url && p.linkedin_url.startsWith('http') ? { linkedin_url: p.linkedin_url.replace(/^http:/, 'https:') } : {}),
        source: `Apollo: ${q.name}`.slice(0, 80), basis: 'legitimate_interest', search_id: q.search_id,
        notes: [p.title, p.city, p.country].filter(Boolean).join(' · ').slice(0, 2000) } } });
    }
  }
}
return out.length ? out : [{ json: { payload: null } }];

// Signs one message for the OS inbound endpoint, exactly as the OS signs its webhooks.
const crypto = require('crypto');
const body = JSON.stringify($json.payload);
const ts = Math.floor(Date.now() / 1000);
const nonce = crypto.randomBytes(16).toString('hex');
const signature = crypto.createHmac('sha256', $env.DP_SIGNING_SECRET).update(`${ts}.${nonce}.${body}`).digest('hex');
return { json: { body, ts: String(ts), nonce, signature } };

// One result for the whole run: failed if any send failed.
const items = $input.all();
const failed = items.filter((i) => i.json && i.json.error);
return [{ json: failed.length ? { error: { message: `${failed.length} of ${items.length} failed: ${String(failed[0].json.error.message || failed[0].json.error).slice(0, 300)}` } } : { sent: items.length } }];

// Signs the result for the OS callback exactly as the OS signs its webhooks.
const crypto = require('crypto');
const run = $('Verify signature').first().json;
const failed = $input.first().json.error;
const body = JSON.stringify({
  run_id: run.run_id,
  organization_id: run.organization_id,
  status: failed ? 'failed' : 'succeeded',
  execution_id: String($execution.id),
  ...(failed ? { error: String(failed.message || failed).slice(0, 1900) } : {}),
});
const ts = Math.floor(Date.now() / 1000);
const nonce = crypto.randomBytes(16).toString('hex');
const signature = crypto.createHmac('sha256', $env.DP_SIGNING_SECRET).update(`${ts}.${nonce}.${body}`).digest('hex');
return [{ json: { body, ts: String(ts), nonce, signature } }];
